$filter = @{ LogName='Security'; Id=4625;
  StartTime=$start }
$event = Get-WinEvent -FilterHashtable $filter `
  -MaxEvents 1
$event | Format-List TimeCreated,Id,RecordId,Message
$event.ToXml()

$lockFilter = @{ LogName='Security'; Id=4740;
  StartTime=$start }
$lockEvent = Get-WinEvent `
  -FilterHashtable $lockFilter -MaxEvents 1
$lockEvent | Format-List TimeCreated,RecordId,Message
$lockEvent.ToXml()

